UPDATE bbs12_application_form
   SET bbs12_public_yn = CASE WHEN #{publicYn} THEN 'true' ELSE 'false' END
 WHERE bbs12_application_form_id = #{applicationFormId}
   AND bbs12_company_id          = #{companyId}

UPDATE bbs12_application_form
   SET bbs12_content      = #{content}
     , bbs12_content_mobi = #{contentMobi}
 WHERE bbs12_application_form_id = #{applicationFormId}
   AND bbs12_company_id          = #{companyId}
